/**
 * SPA 部署基址计算（支持子路径部署，如 https://szf.szzfcjj.cn/test/）。
 *
 * 背景：登录成功/退出登录曾用 window.location.replace('/') 写死站点根，
 * 在 /test/ 这类子目录部署下会丢子路径、跳到另一个项目。此工具按「当前页面
 * 部署目录」计算跳转基址，与 resolveServerAssetUrl.js 的 getAssetResolveBase()
 * 语义对齐（但互不依赖，避免改动生产在用函数）。
 */

/**
 * 计算当前页面的部署目录基址（保证尾斜杠），返回 origin + dir。
 * @param {string} [pathname] 默认 window.location.pathname，便于测试注入
 * @param {string} [origin]   默认 window.location.origin，便于测试注入
 * @returns {string} 如 https://host/test/ 或 https://host/
 */
export function getAppBasePath(pathname, origin) {
  if (typeof window === 'undefined' || !window.location) {
    // 非浏览器环境（如脚本/SSR）直接返回空，调用方应自行处理
    if (pathname == null || origin == null) return ''
  }
  const p =
    pathname != null
      ? pathname
      : typeof window !== 'undefined' && window.location
        ? window.location.pathname
        : '/'
  const o =
    origin != null
      ? origin
      : typeof window !== 'undefined' && window.location
        ? window.location.origin
        : ''

  let dir = p || '/'

  // 与生产在用的 getAssetResolveBase() 同一语义：
  // - .html 结尾：去掉文件名，保留目录（/test/index.html -> /test/）
  // - 其它非尾斜杠：当作目录补尾斜杠（/test -> /test/；/ 保持 /）
  // 说明：/login 这类命名段会被当作 /login/，但本会话已把 401/退出登录改为 #/login
  // （见 api/index.js），登录成功时 pathname 恒为部署目录（/test/ 或 /），
  // 不会再出现 pathname 固化为 /login 的残留，故此处按目录语义处理是安全的。
  if (/\.html?$/i.test(dir)) {
    dir = dir.replace(/[^/]+$/, '')
  }
  if (!dir.endsWith('/')) {
    dir = `${dir}/`
  }

  return `${o}${dir}`
}

/** 整页跳回当前部署根目录（保留 /test 等子路径），用于登录成功后强制重载。 */
export function redirectToAppRoot() {
  window.location.replace(getAppBasePath())
}

/** 整页跳转到当前部署目录下的 hash 登录页（保留 /test 等子路径）。 */
export function redirectToLogin() {
  window.location.replace(`${getAppBasePath()}#/login`)
}

tool_input.new_string:
// 整页跳回部署根目录：hash 路由 push 只改 hash，pathname 残留 /login 会让站内图片 URL 拼上 /login/ 而破图（bug6540）；
// 用部署目录基址（而非写死 '/'）以保留 /test 等子路径部署，避免跳到根域另一个项目。
redirectToAppRoot()
